import 'package:flet/flet.dart';
import 'package:flutter/widgets.dart';
import 'package:image_picker/image_picker.dart';

class NativeCameraControl extends StatefulWidget {
  final Control? parent;
  final Control control;
  final FletControlBackend backend;

  const NativeCameraControl(
      {super.key,
      required this.parent,
      required this.control,
      required this.backend});

  @override
  State<NativeCameraControl> createState() => _NativeCameraControlState();
}

class _NativeCameraControlState extends State<NativeCameraControl>
    with FletStoreMixin {
  final ImagePicker _picker = ImagePicker();

  @override
  void initState() {
    debugPrint("NativeCamera.initState($hashCode)");
    widget.control.onRemove.clear();
    widget.control.onRemove.add(_onRemove);
    super.initState();
  }

  void _onRemove() {
    debugPrint("NativeCamera.remove($hashCode)");
    widget.backend.unsubscribeMethods(widget.control.id);
  }

  Future<String?> _takePicture(String lensDirection) async {
    try {
      final XFile? file = await _picker.pickImage(
        source: ImageSource.camera,
        preferredCameraDevice:
            lensDirection == "front" ? CameraDevice.front : CameraDevice.rear,
      );
      return file?.path;
    } catch (e) {
      widget.backend
          .triggerControlEvent(widget.control.id, "error", e.toString());
      return null;
    }
  }

  @override
  Widget build(BuildContext context) {
    debugPrint("NativeCamera build: ${widget.control.id}");

    () async {
      widget.backend.subscribeMethods(widget.control.id,
          (methodName, args) async {
        switch (methodName) {
          case "take_picture":
            return await _takePicture(args["lensDirection"] ?? "back");
        }
        return null;
      });
    }();

    return const SizedBox.shrink();
  }
}
